import React from 'react';
import './ProductFilter.css';

const ProductFilter = ({ filters, onFilterChange }) => {
    const handleChange = (e) => {
        const { name, value } = e.target;
        onFilterChange({ ...filters, [name]: value });
    };

    return (
        <div className="product-filter">
            <select name="category" value={filters.category || ''} onChange={handleChange}>
                <option value="">All Categories</option>
                <option value="vegetables">Vegetables</option>
                <option value="fruits">Fruits</option>
                <option value="beverages">Beverages</option>
                <option value="canned food">Canned Food</option>
                <option value="dairy">Dairy</option>
                <option value="meat">Meat</option>
                <option value="sea food">Sea Food</option>
                <option value="snacks">Snacks & Sweets</option>
            </select>
            <input type="number" name="minPrice" value={filters.minPrice || ''} onChange={handleChange} placeholder="Min Price" />
            <input type="number" name="maxPrice" value={filters.maxPrice || ''} onChange={handleChange} placeholder="Max Price" />
            <input type="number" name="minDiscount" value={filters.minDiscount || ''} onChange={handleChange} placeholder="Min Discount" />
            <input type="number" name="maxDiscount" value={filters.maxDiscount || ''} onChange={handleChange} placeholder="Max Discount" />
        </div>
    );
};

export default ProductFilter;
